import glob,re
for f in sorted(glob.glob('*.txt')):
 lines=open(f).read().splitlines(); page='?'; out=[]; inds=set()
 for i,l in enumerate(lines):
  if re.search(r'perpet|indefinit|\\bterm\\b|\\bduration\\b',l,re.I) and (re.search(r'perpet|indefinit|duration|"'^.{0,25}'"\\bterm\\b|initial term|shall.*term',l,re.I)):
   inds.update(range(max(0,i-1), min(len(lines),i+5)))
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if i in inds: out.append('p.'+page+': '+l)
 print('\\nFILE '+f[:-4]+'\\n'+'\\n'.join(out))
